rows = [("img_001.jpg", "a1f3", "원본"), ("img_002.jpg", "9c2e", "화면"),
        ("img_003.jpg", "a1f3", "출력"), ("img_004.jpg", "77b0", "원본")]
seen = {}
for name, h, label in rows:
    if h in seen and seen[h][1] != label:
        print(f"같은 사진 다른 라벨: {seen[h][0]}={seen[h][1]} / {name}={label}")
    seen.setdefault(h, (name, label))
# 같은 사진 다른 라벨: img_001.jpg=원본 / img_003.jpg=출력
